import{_ as i,o as u,c as t,a2 as n}from"./chunks/framework.CqpfiAoK.js";const y=JSON.parse('{"title":"Fahirisi ya Vifungu vya Kisheria","description":"","frontmatter":{},"headers":[],"relativePath":"sw/92-法律条文索引.md","filePath":"sw/92-法律条文索引.md","lastUpdated":null}'),k={name:"sw/92-法律条文索引.md"};function w(h,a,m,d,r,e){return u(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="fahirisi-ya-vifungu-vya-kisheria" tabindex="-1">Fahirisi ya Vifungu vya Kisheria <a class="header-anchor" href="#fahirisi-ya-vifungu-vya-kisheria" aria-label="Permalink to &quot;Fahirisi ya Vifungu vya Kisheria&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>92</td></tr><tr><td>Moduli</td><td>Viambatanisho na Vifaa vya Rujia</td></tr><tr><td>Maneno muhimu</td><td>fahirisi ya kisheria, Katiba ya Usawa, sheria ya kazi, sheria ya ulinzi wa watumiaji, sheria za msaada</td></tr></tbody></table><h2 id="_1-maelezo-ya-fahirisi" tabindex="-1">1. Maelezo ya Fahirisi <a class="header-anchor" href="#_1-maelezo-ya-fahirisi" aria-label="Permalink to &quot;1. Maelezo ya Fahirisi&quot;">​</a></h2><p>Fahirisi hii ina hati kuu za kisheria zinazotumika sasa na vifungu vyao vya msingi vya Ustaarabu wa Usawa wa Nanga, iliyopangwa kwa safu ya kisheria na idara. Wigo wa fahirisi unajumuisha &quot;Katiba ya Usawa&quot;, &quot;Sheria ya Kazi ya Usawa&quot;, &quot;Sheria ya Ulinzi wa Watumiaji&quot;, na pia sheria tano za msaada kuhusu elimu, afya, makazi, mazingira, na kuzuia utawala wa soko. Kila kiingilio cha fahirisi kinaorodhesha jina la sheria, nambari ya kifungu, na muhtasari wa maudhui ya msingi ya kifungu. Fahirisi hii ni chombo cha rujia; kwa maandishi kamili ya vifungu vya kisheria na tafsiri za kikortoni, tafadhali rejelea maandishi rasmi ya kila sheria.</p><h2 id="_2-katiba-ya-usawa" tabindex="-1">2. Katiba ya Usawa <a class="header-anchor" href="#_2-katiba-ya-usawa" aria-label="Permalink to &quot;2. Katiba ya Usawa&quot;">​</a></h2><p>&quot;Katiba ya Usawa&quot; ni sheria ya msingi ya Ustaarabu wa Usawa wa Nanga, yenye uwezo wa juu wa kisheria, iliyotungwa wakati wa usanifu rasmi wa ustaarabu wa usawa.</p><table tabindex="0"><thead><tr><th>Nambari ya kifungu</th><th>Maudhui ya msingi</th></tr></thead><tbody><tr><td>Kifungu cha 1</td><td>Inabainisha Hengyuanzhou (Ulimwengu wa Asili wa Wanling Hengmao) kama eneo la utawala wa Ustaarabu wa Usawa wa Nanga; kusudi la msingi la ustaarabu wa usawa ni kufikia usawa wa kabila zote na kuinua kiwango cha ulimwengu</td></tr><tr><td>Kifungu cha 2</td><td>Inabainisha kipingamizi cha kuitoaji kama msimamo wa msingi wa ustaarabu; inakataza aina yoyote ya mazoezi ya kuitoaji na kuitoaji wa rasilimali</td></tr><tr><td>Kifungu cha 3</td><td>Inabainisha &quot;kurudisha haki ya kuchagua hatima na mageuzi kwa viumbe vyote vyenye fahamu&quot; kama wazo la msingi la ustaarabu</td></tr><tr><td>Kifungu cha 4</td><td>Inabainisha kazi nyingi faida nyingi, ukuaji wa kibinafsi, kila mtu ana njia, kabila zote zinaendelea pamoja kama sera za msingi za ustaarabu</td></tr><tr><td>Kifungu cha 5</td><td>Inabainisha mfumo wa kufungua bure kwa mifumo mia tatu ya mazoezi ya asili; hakuna shirika au mtu anaweza kutumia haki ya kupeana mifumo ya mazoezi</td></tr><tr><td>Kifungu cha 6</td><td>Inabainisha utaratibu wa mkataba wa uzalishaji pamoja kama mfumo wa msingi wa mgawanyo wa rasilimali</td></tr><tr><td>Kifungu cha 7</td><td>Inabainisha mkakati wa uanzishaji wa 20% kama lengo la kitaifa la hatua kwa hatua</td></tr><tr><td>Kifungu cha 8</td><td>Inabainisha kanuni ya msingi ya ukweli; ulimwengu wa kweli ndio ulimwengu wa kweli wa pekee, mipangilio ya ubongo haina uwezo wa kisheria</td></tr><tr><td>Kifungu cha 9</td><td>Inabainisha njia ya kuinua kiwango cha hatua nne kama mkakati wa maendeleo ya muda mrefu wa ustaarabu</td></tr><tr><td>Kifungu cha 10</td><td>Inabainisha kanuni ya usawa wa kabila zote; kila aina ya uhai ni sawa mbele ya sheria</td></tr><tr><td>Kifungu cha 11</td><td>Inabainisha kanuni ya mageuzi ya usawa; mageuzi ya kibinafsi hayawezi kufanyika kwa kutoa haki ya mageuzi ya mtu mwingine au kikundi</td></tr><tr><td>Kifungu cha 12</td><td>Inabainisha kanuni ya kazi nyingi faida nyingi; mgawanyo wa rasilimali unachukucha mchango kama msingi wa msingi</td></tr><tr><td>Kifungu cha 13</td><td>Inabainisha kanuni ya ukuaji wa kibinafsi; inaheshimu haki ya kila uhai kuchagua mageuzi kwa uhuru</td></tr><tr><td>Kifungu cha 14</td><td>Inabainisha kanuni ya kila mtu ana njia; serikali ina jukumu la kutoa kila uhai njia ya msingi ya mageuzi na uhakika wa rasilimali</td></tr><tr><td>Kifungu cha 15</td><td>Inabainisha kanuni ya uendelevu; maendeleo yote yanayopaswa kuzingatia uendelevu wa asili ya ulimwengu</td></tr><tr><td>Vifungu 16-25</td><td>Vinaweka haki za msingi za viumbe vyote vyenye fahamu: haki ya kuchagua mageuzi, haki ya kupata rasilimali za mazoezi, haki ya ulinzi wa usawa, haki ya kushiriki katika usawa, haki ya uhifadhi wa utamaduni, haki ya msaada na rufaa, haki ya uhuru wa mwili, haki ya heshima ya binadamu, haki ya uhuru wa imani, haki ya uhuru wa kujieleza</td></tr><tr><td>Vifungu 26-31</td><td>Vinaweka wajibu wa msingi wa viumbe vyote vyenye fahamu: wajibu wa kutii sheria, wajibu wa kudumisha utaratibu wa usawa, wajibu wa mchango wa kazi, wajibu wa kulinda mazingira, wajibu wa kuesa haki za wengine, wajibu wa kuongoza wafanyakazi wa chini</td></tr><tr><td>Kifungu cha 32</td><td>Inabainisha Baraza la Nanga kama mamlaka ya juu, inajumuisha wawakilishi wa kabila zote kwa uwiano</td></tr><tr><td>Kifungu cha 33</td><td>Inabainisha Kamati ya Utendaji wa Usawa kama taasisi ya juu ya usimamizi</td></tr><tr><td>Kifungu cha 34</td><td>Inabainisha Korti ya Usawa kama taasisi ya juu ya mahakama, inatumia mamlaka ya mahakama kwa uhuru</td></tr><tr><td>Kifungu cha 35</td><td>Inabainisha Kamati ya Uangalizi wa Nanga kama taasisi ya uhuru ya uangalizi</td></tr><tr><td>Kifungu cha 36</td><td>Inaweka utaratibu wa utungaji wa sheria: muswada wa sheria unapitishwa kwa多数 zaidi ya nusu ya Baraza la Nanga</td></tr><tr><td>Kifungu cha 37</td><td>Inaweka utaratibu wa marekebisho ya katiba: lazima ipitishwe kwa多数 zaidi ya theluthi mbili za Baraza la Nanga na ikubaliwe zaidi ya nusu ya kura ya taifa</td></tr><tr><td>Kifungu cha 38</td><td>Inabainisha mfumo wa uchunguzi wa katiba; Korti ya Usawa ina haki ya kutangaza sheria zinazokwamisha Katiba kuwa batili</td></tr><tr><td>Kifungu cha 39</td><td>Inabainisha mfumo wa mashtaka ya katiba; viumbe vyote vyenye fahamu vinaweza kuzindua mashtaka moja kwa moja kulingana na Katiba</td></tr><tr><td>Kifungu cha 40</td><td>Inaweka mfumo wa utawala wa wenyeji; kila kisiwa cha nyota na kila usawa unatekelezwa utawala wa wenyeji ndani ya mfumo wa katiba</td></tr><tr><td>Kifungu cha 41</td><td>Inabainisha mfumo wa jamhuri ya kabila zote; makabila yote ni sawa katika ustaarabu wa usawa na wanatekelezwa utawala wa wenyeji wa mkoa</td></tr><tr><td>Kifungu cha 42</td><td>Inaweka mfumo wa uchumi wa ustaarabu wa usawa: kulingana na mikataba ya uzalishaji pamoja, uchumi wa umiliki anuwai unaendelea pamoja</td></tr><tr><td>Kifungu cha 43</td><td>Inaweka mfumo wa umiliki wa serikali na mgawanyo wa haki wa rasilimali za mazoezi</td></tr><tr><td>Kifungu cha 44</td><td>Inabainisha mfumo wa usawa wa elimu, inahakikisha haki ya kila uhai ya elimu ya usawa</td></tr><tr><td>Kifungu cha 45</td><td>Inabainisha mfumo wa uhakika wa afya kwa watu wote</td></tr><tr><td>Kifungu cha 46</td><td>Inabainisha mfumo wa uhakika wa makazi, inahakikisha haki ya msingi ya kila uhai ya makazi</td></tr><tr><td>Kifungu cha 47</td><td>Inaweka kanuni za msingi za mwingiliano kati ya usawa; hakuna safari isiyoidhinishwa kati ya usawa bila idhini</td></tr><tr><td>Kifungu cha 48</td><td>Inaweka kuwa patumbo halali za shughuli za kale zimekomaa kwa maarifa ya kifupi na taarifa; kurudisha vifaa na nishati kunakatazwa</td></tr><tr><td>Kifungu cha 49</td><td>Inaweka kanuni za msingi za kurudia nyuma kwa muda; lazima zifuata kanuni ya kuzingatia kwanza, kisha kuingilia kwa kikomo</td></tr><tr><td>Kifungu cha 50</td><td>Inaweka kuwa haki ya kutafsiri Katiba inamilikiwa na Korti ya Usawa, na haki ya marekebisho ya Katiba inamilikiwa na Baraza la Nanga</td></tr></tbody></table><h2 id="_3-sheria-ya-kazi-ya-usawa" tabindex="-1">3. Sheria ya Kazi ya Usawa <a class="header-anchor" href="#_3-sheria-ya-kazi-ya-usawa" aria-label="Permalink to &quot;3. Sheria ya Kazi ya Usawa&quot;">​</a></h2><p>&quot;Sheria ya Kazi ya Usawa&quot; ni sheria ya msingi inayosimamia uhusiano wa kazi na kulinda haki na maslahi ya wafanyakazi, ikichukua Kifungu cha 42 cha Katiba ya Usawa kama msingi wa utungaji wa sheria.</p><table tabindex="0"><thead><tr><th>Nambari ya kifungu</th><th>Maudhui ya msingi</th></tr></thead><tbody><tr><td>Kifungu cha 1</td><td>Kusudi la utungaji wa sheria: kusimamia uhusiano wa kazi, kulinda haki na maslahi halali ya wafanyakazi, na kujenga uhusiano wa kazi ulio na umoja na usawa</td></tr><tr><td>Kifungu cha 2</td><td>Wigo wa utekelezaji: uhusiano wote wa kazi ndani ya Hengyuanzhou, ikiwa ni pamoja na kazi ya vifaa, kazi ya mazoezi, na kazi ya ubunifu</td></tr><tr><td>Kifungu cha 3</td><td>Inabainisha kanuni ya ajira ya usawa kwa wafanyakazi; inakataza ubaguzi wa ajira kulingana na kabila, jinsia, kiwango cha mazoezi, au asili</td></tr><tr><td>Kifungu cha 4</td><td>Inabainisha kanuni ya uhuru wa kuchagua kazi kwa wafanyakazi; inakataza kazi ya kulazimisha na utumwa</td></tr><tr><td>Kifungu cha 5</td><td>Inaweka mfumo wa mkataba wa kazi; wakati wa usanifu wa uhusiano wa kazi, lazima tusaini mkataba wa kazi wa maandishi</td></tr><tr><td>Kifungu cha 6</td><td>Inaweka masharti ya lazima ya mkataba wa kazi: muda wa mkataba, maudhui ya kazi, malipo ya kazi, muda wa kazi, ulinzi wa kazi, bima ya jamii</td></tr><tr><td>Kifungu cha 7</td><td>Inabainisha mfumo wa saa nane za kazi na mfumo wa muda wa kazi usiozidi saa arobaini na nne kwa wiki</td></tr><tr><td>Kifungu cha 8</td><td>Inaweka vizuizi vya kazi ya ziada: kazi ya ziada ya kila siku haifai kuzidi saa moja, hali maalum haifai kuzidi saa tatu, kazi ya ziada ya kila mwezi haifai kuzidi saa thelathini na sita</td></tr><tr><td>Kifungu cha 9</td><td>Inaweka viwango vya malipo ya kazi ya ziada: mara 1.5 ya malipo kwa kazi ya ziada siku za kazi, mara 2 ya malipo kwa kazi ya ziada siku za pumziko, mara 3 ya malipo kwa kazi ya ziada siku za likizo za kisheria</td></tr><tr><td>Kifungu cha 10</td><td>Inabainisha mfumo wa uhakika wa malipo ya chini; viwango vya malipo ya chini vinawekwa na kila kisiwa cha nyota kulingana na hali za eneo</td></tr><tr><td>Kifungu cha 11</td><td>Inaweka mfumo wa malipo ya malipo: malipo yanayopaswa kulipwa kila mwezi kwa mwenyewe wa mfanyakazi kwa njia ya fedha, na hayapaswi kukatwa au kucheleweshwa bila sababu</td></tr><tr><td>Kifungu cha 12</td><td>Inabainisha kanuni ya mgawanyo wa kazi nyingi faida nyingi; inatekelezwa mfumo wa mgawanyo ulio na mgawanyo kulingana na kazi kama msingi wa msingi na mbinu anuwai za mgawanyo ziko pamoja</td></tr><tr><td>Kifungu cha 13</td><td>Inaweka mfumo wa usalama na afya ya kazi; wafanyakazi waajiri wanayopaswa kutoa wafanyakazi hali za usalama na afya za kazi zinazofuata viwango</td></tr><tr><td>Kifungu cha 14</td><td>Inaweka ulinzi wa vikundi maalum: ulinzi maalum wa kazi kwa wafanyakazi wadogo, wafanyakazi wa kike, wafanyakazi wenye ulemavu, na wafanyakazi wa mazoezi ya chini</td></tr><tr><td>Kifungu cha 15</td><td>Inabainisha mfumo wa mafunzo ya ufundi; wafanyakazi waajiri wana jukumu la kufanya mafunzo ya ufundi kwa wafanyakazi</td></tr><tr><td>Kifungu cha 16</td><td>Inaweka haki na maslahi ya kazi ya wataalamu wa mazoezi: kazi ya mazoezi pia inalindwa na sheria hii; umiliki wa matokeo ya mazoezi unakubaliana na mkataba</td></tr><tr><td>Kifungu cha 17</td><td>Inabainisha mfumo wa bima ya jamii ya wafanyakazi: bima ya miujiza, bima ya afya, bima ya ukosefu wa ajira, bima ya majeraha ya kazi, bima ya uzazi</td></tr><tr><td>Kifungu cha 18</td><td>Inaweka mfumo wa ustawi wa wafanyakazi; wafanyakazi waajiri wanayopaswa kutoa wafanyakazi maslahi ya ustawi yanayohitajika</td></tr><tr><td>Kifungu cha 19</td><td>Inabainisha mfumo wa usumbufu wa kazi: utaratibu wa usumbufu wa viwango vinne vya mazungumzo, upatanisho, arbitraji, na mashtaka</td></tr><tr><td>Kifungu cha 20</td><td>Inaweka mfumo wa vyama vya wafanyakazi; wafanyakazi wana haki ya kuanzisha na kujiunga na vyama vya wafanyakazi kulingana na sheria ili kulinda haki na maslahi yao halali</td></tr><tr><td>Kifungu cha 21</td><td>Inaweka mfumo wa mkataba wa pamoja; vyama vya wafanyakazi vinawakilisha wafanyakazi kusaini mkataba wa pamoja na wafanyakazi waajiri</td></tr><tr><td>Kifungu cha 22</td><td>Inaweka kuwa kanuni za wafanyakazi waajiri lazima zikubadilishwe na mkutano wa wawakilishi wa wafanyakazi au wafanyakazi wote</td></tr><tr><td>Kifungu cha 23</td><td>Inaweka masharti na utaratibu wa kumaliza mkataba wa kazi</td></tr><tr><td>Kifungu cha 24</td><td>Inaweka mfumo wa fidia ya kiuchumi; wafanyakazi waajiri wanayopaswa kulipa fidia ya kiuchumi wakati wa kumaliza mkataba wa kazi kulingana na sheria</td></tr><tr><td>Kifungu cha 25</td><td>Inaweka mfumo wa fidia kwa kumaliza mkataba wa kazi kwa kinyume cha sheria</td></tr><tr><td>Kifungu cha 26</td><td>Inabainisha mfumo wa usimamizi wa utumishi wa kazi, inasimamia ajira ya utumishi wa kazi</td></tr><tr><td>Kifungu cha 27</td><td>Inaweka kanuni maalum kwa ajira ya muda wa nusu</td></tr><tr><td>Kifungu cha 28</td><td>Inaweka mfumo wa uangalizi na ukaguzi; idara za usimamizi wa kazi zinazangalia na kukagua utekelezaji wa sheria na kanuni za kazi na wafanyakazi waajiri kulingana na sheria</td></tr><tr><td>Kifungu cha 29</td><td>Inaweka wajibu wa kisheria: wafanyakazi waajiri wanaovunja sheria hii watachukua wajibu wa usimamizi, wa kiraia, na wa jinai kulingana na sheria</td></tr><tr><td>Kifungu cha 30</td><td>Inaweka tarehe ya utekelezaji na haki ya kutafsiri sheria hii</td></tr></tbody></table><h2 id="_4-sheria-ya-ulinzi-wa-watumiaji" tabindex="-1">4. Sheria ya Ulinzi wa Watumiaji <a class="header-anchor" href="#_4-sheria-ya-ulinzi-wa-watumiaji" aria-label="Permalink to &quot;4. Sheria ya Ulinzi wa Watumiaji&quot;">​</a></h2><p>&quot;Sheria ya Ulinzi wa Watumiaji&quot; ni sheria ya msingi inayolinda haki na maslahi halali ya watumiaji na inasimamia tabia ya wafanyabiashara.</p><table tabindex="0"><thead><tr><th>Nambari ya kifungu</th><th>Maudhui ya msingi</th></tr></thead><tbody><tr><td>Kifungu cha 1</td><td>Kusudi la utungaji wa sheria: kulinda haki na maslahi halali ya watumiaji, kudumisha utaratibu wa kijamii na kiuchumi, na kukuza ukuzaji wenye afya wa uchumi wa soko wa usawa</td></tr><tr><td>Kifungu cha 2</td><td>Wigo wa utekelezaji: ulinzi wa haki na maslahi ya watumiaji ndani ya Hengyuanzhou ambao wanunua, wanatumia bidhaa, au wanapokea huduma kwa mahitaji ya matumizi ya kila siku</td></tr><tr><td>Kifungu cha 3</td><td>Inabainisha kanuni za msingi za biashara kati ya wafanyabiashara na watumiaji: hiari, usawa, haki, uaminifu, na uaminifu</td></tr><tr><td>Kifungu cha 4</td><td>Inabainisha kanuni ya ulinzi wa serikali kwa haki na maslahi halali ya watumiaji; serikali inachukua hatua za kuhakikisha watumiaji wanatumia haki zao kulingana na sheria</td></tr><tr><td>Kifungu cha 5</td><td>Inaweka haki tisa za msingi za watumiaji: haki ya usalama, haki ya kujua, haki ya kuchagua kwa hiari, haki ya biashara ya haki, haki ya fidia, haki ya kujiunga na shirika, haki ya kupata maarifa, haki ya kuheshimiwa, haki ya uangalizi</td></tr><tr><td>Kifungu cha 6</td><td>Inaweka haki ya usalama ya watumiaji: watumiaji wanafurahia haki ya kuwa usalama wa mwili na mali haukabili na madhara wakati wa kununua, kutumia bidhaa, na kupokea huduma</td></tr><tr><td>Kifungu cha 7</td><td>Inaweka haki ya kujua ya watumiaji: watumiaji wanafurahia haki ya kujua hali halisi ya bidhaa wanazonunua au kutumia au huduma wanazopokea</td></tr><tr><td>Kifungu cha 8</td><td>Inaweka haki ya kuchagua kwa hiari ya watumiaji: watumiaji wanafurahia haki ya kuchagua bidhaa au huduma kwa hiari</td></tr><tr><td>Kifungu cha 9</td><td>Inaweka haki ya biashara ya haki ya watumiaji: watumiaji wanafurahia haki ya biashara ya haki na wana haki ya kukataa tabia ya biashara ya kulazimisha</td></tr><tr><td>Kifungu cha 10</td><td>Inaweka haki ya fidia ya watumiaji: watumiaji ambao wamepata madhara ya mwili au mali kutokana na kununua, kutumia bidhaa, au kupokea huduma wanafurahia haki ya kupata fidia kulingana na sheria</td></tr><tr><td>Kifungu cha 11</td><td>Inaweka wajibu wa msingi wa wafanyabiashara: kutekeleza wajibu wa kisheria na wa mkataba, kukubali uangalizi, kuhakikisha usalama, kutoa taarifa za kweli, kutoa hati, kuhakikisha ubora, kutekeleza ulinzi wa tatu, kutofanya biashara isiyo ya haki, kutokwamisha utu</td></tr><tr><td>Kifungu cha 12</td><td>Inaweka wajibu wa uhakika wa usalama wa wafanyabiashara: wafanyabiashara wanayopaswa kuhakikisha bidhaa au huduma wanazotoa zinafuata mahitaji ya ulinzi wa usalama wa mwili na mali</td></tr><tr><td>Kifungu cha 13</td><td>Inaweka wajibu wa kufichua taarifa wa wafanyabiashara: wafanyabiashara wanayopaswa kutoa watumiaji taarifa za kweli kuhusu bidhaa au huduma, na hawapaswi kufanya matangazo ya uongo au yanayopotosha</td></tr><tr><td>Kifungu cha 14</td><td>Inaweka viwango maalum kwa bidhaa na huduma za mazoezi: wafanyabiashara wa mbinu za mazoezi, vyombo vya mazoezi, na bidhaa za nishati wanayopaswa kuwa na sifa maalum, na bidhaa lazima vipite ushahidi wa usalama</td></tr><tr><td>Kifungu cha 15</td><td>Inaweka udhibiti wa masharti ya kiwango; wafanyabiashara hawanawezi kuondoa au kupunguza haki za watumiaji, kupunguza au kusamehesha wajibu wa wafanyabiashara kupitia masharti ya kiwango</td></tr><tr><td>Kifungu cha 16</td><td>Inabainisha mfumo wa kurudisha bidhaa bila sababu kwa siku saba; watumiaji wanunua bidhaa kupitia mbinu za mbali kama intaneti wana haki ya kurudisha bidhaa ndani ya siku saba kuanzia tarehe ya kupokea bidhaa</td></tr><tr><td>Kifungu cha 17</td><td>Inabainisha mfumo wa ulinzi wa tatu; ikiwa bidhaa au huduma zilizotolewa na wafanyabiashara hazifuati mahitaji ya ubora, watumiaji wanaweza kuomba ukarabati, uingizwaji, au urudishaji kulingana na kanuni za serikali</td></tr><tr><td>Kifungu cha 18</td><td>Inabainisha mfumo wa fidia ya adhabu; ikiwa wafanyabiashara wana tabia ya udanganyifu katika kutoa bidhaa au huduma, wanayopaswa kuongeza fidia kwa madhara ya watumiaji kulingana na ombi la watumiaji, na kiwango cha fidia iliyoongezwa lazima kiwe mara tatu ya bei ya bidhaa watumiaji wamekunua au gharama ya huduma iliyopokelewa</td></tr><tr><td>Kifungu cha 19</td><td>Inaweka shirika za watumiaji; vyama vya watumiaji na shirika zingine za watumiaji ni shirika za kijamii zilizoundwa kulingana na sheria zinazofanya uangalizi wa kijamii kwa bidhaa na huduma ili kulinda haki na maslahi halali ya watumiaji</td></tr><tr><td>Kifungu cha 20</td><td>Inaweka njia za kutatua usumbufu wa watumiaji: mazungumzo na makubaliano na wafanyabiashara, ombi la upatanisho wa chama cha watumiaji, rufaa kwa idara za usimamizi zinazohusiana, ombi la arbitraji, kuwasilisha mashtaka kortini</td></tr><tr><td>Kifungu cha 21</td><td>Inaweka uhamisho wa mzigo wa ushahidi katika usumbufu; kwa bidhaa za kudumu au huduma kama mapambo, ikiwa watumiaji wanagundua kasoro ndani ya miezi sita kuanzia tarehe ya kupokelea, wafanyabiashara wanabeba mzigo wa ushahidi</td></tr><tr><td>Kifungu cha 22</td><td>Inaweka wajibu wa usimamizi na wa jinai wa wafanyabiashara</td></tr><tr><td>Kifungu cha 23</td><td>Inaweka tarehe ya utekelezaji na haki ya kutafsiri sheria hii</td></tr></tbody></table><h2 id="_5-sheria-tano-za-msaada" tabindex="-1">5. Sheria Tano za Msaada <a class="header-anchor" href="#_5-sheria-tano-za-msaada" aria-label="Permalink to &quot;5. Sheria Tano za Msaada&quot;">​</a></h2><h3 id="_5-1-sheria-ya-uhakika-wa-elimu" tabindex="-1">5.1 Sheria ya Uhakika wa Elimu <a class="header-anchor" href="#_5-1-sheria-ya-uhakika-wa-elimu" aria-label="Permalink to &quot;5.1 Sheria ya Uhakika wa Elimu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nambari ya kifungu</th><th>Maudhui ya msingi</th></tr></thead><tbody><tr><td>Kifungu cha 1</td><td>Kusudi la utungaji wa sheria: kuhakikisha haki ya elimu ya usawa ya viumbe vyote vyenye fahamu, kujenga mfumo wa elimu ya usawa, na kukuza ukuzaji wa pamoja wa utamaduni wa kabila zote</td></tr><tr><td>Vifungu 2-5</td><td>Vinabainisha kanuni ya usawa wa elimu, kanuni ya elimu ya bure (kiwango cha elimu ya msingi), kanuni ya utofauti wa elimu, kanuni ya ubunifu wa elimu</td></tr><tr><td>Vifungu 6-10</td><td>Vinaweka muundo wa mfumo wa elimu ya awali, elimu ya lazima, elimu ya shule ya sekondari, elimu ya juu, elimu ya mazoezi</td></tr><tr><td>Vifungu 11-15</td><td>Vinaweka mifumo maalum kwa elimu ya mazoezi: viwango vya kufundishia vya mifumo mia tatu, mfumo wa walimu, mfumo wa mgawanyo wa rasilimali za mazoezi</td></tr><tr><td>Vifungu 16-20</td><td>Vinaweka haki na wajibu wa walimu, mfumo wa sifa za walimu, uhakika wa malipo ya walimu</td></tr><tr><td>Vifungu 21-25</td><td>Vinaweka uhakika wa uwekezaji wa elimu, ujenzi wa vifaa vya elimu, teknolojia ya habari katika elimu, elimu maalum, elimu kati ya kabila</td></tr><tr><td>Vifungu 26-30</td><td>Vinaweka mfumo wa tathmini ya elimu, mfumo wa uangalizi wa elimu, wajibu wa kisheria na kanuni za ziada</td></tr></tbody></table><h3 id="_5-2-sheria-ya-uhakika-wa-afya" tabindex="-1">5.2 Sheria ya Uhakika wa Afya <a class="header-anchor" href="#_5-2-sheria-ya-uhakika-wa-afya" aria-label="Permalink to &quot;5.2 Sheria ya Uhakika wa Afya&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nambari ya kifungu</th><th>Maudhui ya msingi</th></tr></thead><tbody><tr><td>Kifungu cha 1</td><td>Kusudi la utungaji wa sheria: kujenga mfumo wa uhakika wa afya kwa watu wote, kuhakikisha haki ya afya ya viumbe vyote vyenye fahamu, na kuboresha kiwango cha jumla cha afya cha kabila zote</td></tr><tr><td>Vifungu 2-5</td><td>Vinabainisha kanuni ya bima ya afya kwa watu wote, kanuni ya dawa ya msingi ya bure, kanuni ya mchanganyiko wa dawa ya Kichina na ya Magharibi, kanuni ya kujumuisha dawa ya mazoezi</td></tr><tr><td>Vifungu 6-10</td><td>Vinaweka mfumo wa bima ya afya ya viwango vingi vya bima ya afya ya msingi, bima ya magonjwa makubwa, msaada wa dawa, bima ya afya ya kibiashara</td></tr><tr><td>Vifungu 11-15</td><td>Vinaweka usimamizi wa taasisi za dawa, mfumo wa wafanyakazi wa dawa, ubora na usalama wa dawa, viwango maalum kwa dawa ya mazoezi</td></tr><tr><td>Vifungu 16-20</td><td>Vinaweka usimamizi wa dawa, usimamizi wa vifaa vya dawa, usimamizi wa bidhaa za dawa za nishati, mfumo wa dawa muhimu</td></tr><tr><td>Vifungu 21-25</td><td>Vinaweka mfumo wa afya ya umma, kuzuia na kudhibiti magonjwa, elimu ya afya, dawa kati ya kabila, uhakika wa afya kwa vikundi maalum</td></tr><tr><td>Vifungu 26-30</td><td>Vinaweka kutatua usumbufu wa dawa, uangalizi wa dawa, wajibu wa kisheria na kanuni za ziada</td></tr></tbody></table><h3 id="_5-3-sheria-ya-uhakika-wa-makazi" tabindex="-1">5.3 Sheria ya Uhakika wa Makazi <a class="header-anchor" href="#_5-3-sheria-ya-uhakika-wa-makazi" aria-label="Permalink to &quot;5.3 Sheria ya Uhakika wa Makazi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nambari ya kifungu</th><th>Maudhui ya msingi</th></tr></thead><tbody><tr><td>Kifungu cha 1</td><td>Kusudi la utungaji wa sheria: kuhakikisha haki ya msingi ya makazi ya viumbe vyote vyenye fahamu, kujenga mfumo wa uhakika wa makazi wa viwango vingi, na kufikia makazi kwa kila mtu</td></tr><tr><td>Vifungu 2-5</td><td>Vinabainisha kanuni ya uhakika wa haki ya makazi, kanuni ya usawa wa makazi, kanuni ya kukopesha na kununua pamoja, kanuni ya makazi yanayodumu</td></tr><tr><td>Vifungu 6-10</td><td>Vinaweka mfumo wa ugavi wa makazi wa makazi ya kupangisha ya umma, makazi ya kupangisha yenye uhakika, makazi yenye umiliki pamoja, makazi ya kibiashara</td></tr><tr><td>Vifungu 11-15</td><td>Vinaweka mfumo wa mfuko wa akiba ya makazi, mfumo wa ruzuku ya makazi, sera ya msaada wa makazi ya kwanza, sera maalum ya makazi kwa wataalamu wa mazoezi</td></tr><tr><td>Vifungu 16-20</td><td>Vinaweka viwango vya ujenzi wa makazi, utekelezaji wa teknolojia ya anga katika makazi, majengo ya kijani, makazi yanayofaa kwa wazee na yasiyo na vizuizi</td></tr><tr><td>Vifungu 21-25</td><td>Vinaweka udhibiti wa soko la mali isiyohamishika, udhibiti wa soko la kupangisha makazi, usimamizi wa huduma za mali, uhakika wa matengenezo ya makazi</td></tr><tr><td>Vifungu 26-30</td><td>Vinaweka uangalizi wa uhakika wa makazi, wajibu wa kisheria na kanuni za ziada</td></tr></tbody></table><h3 id="_5-4-sheria-ya-ulinzi-wa-mazingira" tabindex="-1">5.4 Sheria ya Ulinzi wa Mazingira <a class="header-anchor" href="#_5-4-sheria-ya-ulinzi-wa-mazingira" aria-label="Permalink to &quot;5.4 Sheria ya Ulinzi wa Mazingira&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nambari ya kifungu</th><th>Maudhui ya msingi</th></tr></thead><tbody><tr><td>Kifungu cha 1</td><td>Kusudi la utungaji wa sheria: kulinda na kuboresha mazingira, kuzuia na kudhibiti uchafuzi na madhara mengine ya umma, kuhakikisha afya ya umma, kukuza ujenzi wa ustaarabu wa mazingira ya ulimwengu, na kukuza maendeleo yanayodumu</td></tr><tr><td>Vifungu 2-5</td><td>Vinabainisha kanuni ya kipaumbele cha ulinzi, kanuni ya kuzuia kwanza, kanuni ya usimamizi wa jumla, kanuni ya kushiriki kwa umma, kanuni ya mtu anayesababisha madhara anachukua wajibu</td></tr><tr><td>Vifungu 6-10</td><td>Vinaweka mfumo wa uangalizi na usimamizi wa mazingira, mfumo wa viwango vya mazingira, mfumo wa tathmini ya athari za mazingira, mfumo wa ufuatiliaji wa mazingira, usimamizi wa mazingira kati ya usawa</td></tr><tr><td>Vifungu 11-15</td><td>Vinaweka kuzuia na kudhibiti uchafuzi wa hewa, kuzuia na kudhibiti uchafuzi wa maji, kuzuia na kudhibiti uchafuzi wa udongo, kuzuia na kudhibiti uchafuzi wa nishati, kuzuia na kudhibiti uchafuzi wa kanuni</td></tr><tr><td>Vifungu 16-20</td><td>Vinaweka usimamizi wa takataka ngumu, kuzuia na kudhibiti uchafuzi wa sauti, kuzuia na kudhibiti uchafuzi wa mionzi, ulinzi wa mazingira, ulinzi wa utofauti wa viumbe</td></tr><tr><td>Vifungu 21-25</td><td>Vinaweka udhibiti wa athari za mazingira za shughuli za mazoezi, ulinzi wa mazingira wa uchimbaji wa nishati, mahitaji ya mazingira ya kale kati ya usawa</td></tr><tr><td>Vifungu 26-30</td><td>Vinaweka kufichua taarifa na kushiriki kwa umma, mashtaka ya maslahi ya umma ya mazingira, wajibu wa kisheria na kanuni za ziada</td></tr></tbody></table><h3 id="_5-5-sheria-ya-kuzuia-utawala-wa-soko" tabindex="-1">5.5 Sheria ya Kuzuia Utawala wa Soko <a class="header-anchor" href="#_5-5-sheria-ya-kuzuia-utawala-wa-soko" aria-label="Permalink to &quot;5.5 Sheria ya Kuzuia Utawala wa Soko&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nambari ya kifungu</th><th>Maudhui ya msingi</th></tr></thead><tbody><tr><td>Kifungu cha 1</td><td>Kusudi la utungaji wa sheria: kuzuia na kuzuia tabia za utawala wa soko, kulinda ushindani wa haki wa soko, kuboresha ufanisi wa utekelezaji wa uchumi, kulinda maslahi ya watumiaji na maslahi ya umma ya kijamii, na kukuza ukuzaji wenye afya wa uchumi wa soko wa usawa</td></tr><tr><td>Vifungu 2-5</td><td>Vinabainisha msimamo wa msingi wa sera ya ushindani, mfumo wa uchunguzi wa ushindani wa haki, kuzuia mikataba ya utawala wa soko, kuzuia kutumia uwezo wa juu wa soko, udhibiti wa umoja wa wafanyabiashara</td></tr><tr><td>Vifungu 6-10</td><td>Vinaweka utambuzi na ubatilisho wa mikataba ya utawala wa soko, mikataba ya utawala wa soko ya usawa, mikataba ya utawala wa soko ya wima, tabia za utawala wa soko za vyama vya tasnia</td></tr><tr><td>Vifungu 11-15</td><td>Vinaweka utambuzi wa uwezo wa juu wa soko, aina za tabia za kutumia uwezo wa juu wa soko, kuzuia kuweka bei za kuitoaji</td></tr><tr><td>Vifungu 16-20</td><td>Vinaweka viwango vya tangazo la umoja wa wafanyabiashara, utaratibu wa uchunguzi, masharti ya vizuizi ya ziada, uamuzi wa kuzuia umoja</td></tr><tr><td>Vifungu 21-25</td><td>Vinaweka kuzuia maalum kwa utawala wa soko wa mfumo wa mazoezi: kuzuia kutumia mbinu za mazoezi, kuzuia utawala wa soko wa rasilimali za mazoezi, kuzuia utawala wa soko wa mtandao wa walimu</td></tr><tr><td>Vifungu 26-30</td><td>Vinaweka taasisi za utekelezaji wa sheria ya kuzuia utawala wa soko, utaratibu wa uchunguzi, wajibu wa kisheria, mfumo wa msamaha na kanuni za ziada</td></tr></tbody></table><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Fahirisi ya Vifungu vya Kisheria ni ramani ya rujia ya mfumo wa utawala kulingana na sheria wa Ustaarabu wa Usawa wa Nanga. Kuanzia Katiba ya Usawa kama sheria ya msingi, hadi Sheria ya Kazi na Sheria ya Ulinzi wa Watumiaji zinazosimamia maisha ya watu, kisha sheria tano za msaada, zinaunda pamoja mfumo kamili wa sheria &quot;ulio na Katiba kama kiongozi, sheria za msingi kama misingi, na sheria za msaada kama msaada&quot;. Mfumo huu unahakikisha shughuli zote za ustaarabu wa usawa zinaendelea kwenye njia ya utawala kulingana na sheria, na kutoa uhakika thabiti wa misingi kwa maendeleo ya pamoja ya kabila zote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-Misingi ya Katiba ya Usawa</li><li>41-Sheria ya Kazi ya Usawa</li><li>48-Mfumo wa Mahakama na Mbinu ya Hukumu</li></ul>',28)])])}const z=i(k,[["render",w]]);export{y as __pageData,z as default};
